{
  "name": "Gemini Image Transformer",
  "description": "A dark-themed image editor using Gemini 2.5 Flash for intelligent transformations, featuring quick actions and before/after comparisons."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface GeneratedImage {
  id: string;
  dataUrl: string; // Base64 or URL
  prompt: string;
  timestamp: number;
}

export enum TransformationType {
  ADD_TREES = 'Add lush green trees and vegetation',
  ADD_WATER = 'Add a body of water, flooding, or river',
  REMOVE_CARS = 'Remove all cars, vehicles, and traffic, replacing them with empty street or background',
  CUSTOM = 'Custom'
}

export interface ProcessingState {
  isProcessing: boolean;
  statusMessage?: string;
}

import { GoogleGenAI } from "@google/genai";

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables");
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Transforms an image using Gemini 2.5 Flash Image model.
 * @param imageBase64 The base64 string of the image (without prefix usually, but we handle cleaning).
 * @param prompt The transformation instruction.
 * @returns The transformed image as a base64 string.
 */
export const transformImage = async (imageBase64: string, prompt: string): Promise<string> => {
  const ai = getAiClient();

  // Clean base64 string if it contains metadata prefix
  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Good balance of speed and editing capability
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png', // Assume PNG or generally compatible type for upload
              data: cleanBase64,
            },
          },
          {
            text: `Edit this image: ${prompt}. Return only the edited image.`,
          },
        ],
      },
      // Note: nano banana models (flash-image) do not support responseMimeType or schemas nicely for images yet in all contexts,
      // but generateContent with image output is standard.
    });

    // Extract image from response
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data returned from Gemini.");

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { GripVertical } from 'lucide-react';

interface BeforeAfterSliderProps {
  originalImage: string;
  modifiedImage: string;
  className?: string;
}

export const BeforeAfterSlider: React.FC<BeforeAfterSliderProps> = ({
  originalImage,
  modifiedImage,
  className = '',
}) => {
  const [sliderPosition, setSliderPosition] = useState(50);
  const [isDragging, setIsDragging] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const handleMove = useCallback((clientX: number) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      const x = Math.max(0, Math.min(clientX - rect.left, rect.width));
      const percentage = (x / rect.width) * 100;
      setSliderPosition(percentage);
    }
  }, []);

  const handleMouseDown = () => setIsDragging(true);
  const handleTouchStart = () => setIsDragging(true);

  const handleMouseUp = () => setIsDragging(false);
  const handleTouchEnd = () => setIsDragging(false);

  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (isDragging) handleMove(e.clientX);
  }, [isDragging, handleMove]);

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (isDragging) handleMove(e.touches[0].clientX);
  }, [isDragging, handleMove]);

  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mouseup', handleMouseUp);
      document.addEventListener('touchend', handleTouchEnd);
    } else {
      document.removeEventListener('mouseup', handleMouseUp);
      document.removeEventListener('touchend', handleTouchEnd);
    }
    return () => {
      document.removeEventListener('mouseup', handleMouseUp);
      document.removeEventListener('touchend', handleTouchEnd);
    };
  }, [isDragging]);

  return (
    <div 
      ref={containerRef}
      className={`relative w-full h-full overflow-hidden rounded-xl select-none cursor-crosshair group ${className}`}
      onMouseMove={handleMouseMove}
      onTouchMove={handleTouchMove}
    >
      {/* Background Image (Modified - After) */}
      <img
        src={modifiedImage}
        alt="After"
        className="absolute top-0 left-0 w-full h-full object-contain bg-gray-900"
      />

      {/* Foreground Image (Original - Before) - Clipped */}
      <div
        className="absolute top-0 left-0 h-full w-full bg-gray-900"
        style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}
      >
        <img
          src={originalImage}
          alt="Before"
          className="absolute top-0 left-0 w-full h-full object-contain"
        />
        {/* Label for Before */}
        <div className="absolute top-4 left-4 bg-black/60 text-white text-xs font-bold px-2 py-1 rounded backdrop-blur-sm">
          BEFORE
        </div>
      </div>

      {/* Label for After */}
      <div className="absolute top-4 right-4 bg-black/60 text-white text-xs font-bold px-2 py-1 rounded backdrop-blur-sm">
        AFTER
      </div>

      {/* Slider Handle */}
      <div
        className="absolute top-0 bottom-0 w-1 bg-white cursor-ew-resize hover:shadow-[0_0_10px_rgba(255,255,255,0.5)] transition-shadow"
        style={{ left: `${sliderPosition}%` }}
        onMouseDown={handleMouseDown}
        onTouchStart={handleTouchStart}
      >
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full flex items-center justify-center shadow-lg transform active:scale-110 transition-transform">
          <GripVertical className="text-gray-800 w-5 h-5" />
        </div>
      </div>
    </div>
  );
};

