import React, { useState } from 'react';
import { Wand2, Loader2 } from 'lucide-react';

interface TransformationPanelProps {
  onTransform: (prompt: string) => void;
  isProcessing: boolean;
}

export const TransformationPanel: React.FC<TransformationPanelProps> = ({ onTransform, isProcessing }) => {
  const [prompt, setPrompt] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (prompt.trim()) {
      onTransform(prompt);
      setPrompt('');
    }
  };

  return (
    <div className="bg-gray-800 rounded-xl p-5 border border-gray-700">
      <h3 className="text-sm font-semibold text-gray-400 uppercase tracking-wider mb-4 flex items-center gap-2">
        <Wand2 className="w-4 h-4" />
        Custom Transform
      </h3>
      <form onSubmit={handleSubmit} className="flex flex-col gap-3">
        <textarea
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="Describe how to change the image... (e.g. 'Make it sunset', 'Add a cat')"
          className="w-full bg-gray-900 text-gray-200 text-sm p-3 rounded-lg border border-gray-700 focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-colors resize-none h-24 placeholder-gray-500"
          disabled={isProcessing}
        />
        <button
          type="submit"
          disabled={!prompt.trim() || isProcessing}
          className="w-full bg-blue-600 hover:bg-blue-500 text-white font-medium py-2.5 rounded-lg transition-colors flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isProcessing ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Processing...
            </>
          ) : (
            <>
              Generate
            </>
          )}
        </button>
      </form>
    </div>
  );
};

