import React, { useState, useEffect } from 'react';
import { Upload, AlertCircle, Sparkles, Download } from 'lucide-react';
import { BeforeAfterSlider } from './components/BeforeAfterSlider';
import { QuickActions } from './components/QuickActions';
import { TransformationPanel } from './components/TransformationPanel';
import { Gallery } from './components/Gallery';
import { transformImage } from './services/geminiService';
import { GeneratedImage, ProcessingState } from './types';

export default function App() {
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [currentImage, setCurrentImage] = useState<string | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [processing, setProcessing] = useState<ProcessingState>({ isProcessing: false });
  const [error, setError] = useState<string | null>(null);

  // Load sample image on mount if none selected
  useEffect(() => {
    // Placeholder to make the UI look populated initially if desired
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const result = event.target?.result as string;
      setOriginalImage(result);
      setCurrentImage(result); // Reset current to original
      setError(null);
    };
    reader.readAsDataURL(file);
  };

  const handleTransform = async (prompt: string) => {
    if (!originalImage) return;

    setProcessing({ isProcessing: true, statusMessage: 'Dreaming up changes...' });
    setError(null);

    try {
      // Always use the ORIGINAL image as the base for new transforms in this UI flow
      // or use currentImage if we want to chain edits?
      // Requirement says "Before/After slider to see the latest change".
      // Usually, users want to chain edits or compare to original.
      // Let's assume chaining edits (using currentImage as source) for maximum fun,
      // but comparing against the initial upload for the slider is often more dramatic.
      // However, chaining allows "Remove cars" THEN "Add trees".
      // Let's use currentImage as source.

      const sourceImage = currentImage || originalImage;
      const newImageData = await transformImage(sourceImage, prompt);

      const newImageEntry: GeneratedImage = {
        id: Date.now().toString(),
        dataUrl: newImageData,
        prompt: prompt,
        timestamp: Date.now(),
      };

      setHistory((prev) => [newImageEntry, ...prev]);
      setCurrentImage(newImageData);
    } catch (err: any) {
      setError(err.message || "Failed to transform image");
    } finally {
      setProcessing({ isProcessing: false });
    }
  };

  const handleHistorySelect = (img: GeneratedImage) => {
    setCurrentImage(img.dataUrl);
  };

  const handleDownload = () => {
    if (!currentImage) return;
    const link = document.createElement('a');
    link.href = currentImage;
    link.download = `gemini-edit-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="min-h-screen bg-[#0d1117] text-gray-200 selection:bg-blue-500/30">
      {/* Header */}
      <header className="border-b border-gray-800 bg-[#161b22]/80 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-gradient-to-br from-blue-500 to-purple-600 p-2 rounded-lg">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-400">
              Gemini Vision
            </h1>
          </div>

          <div className="flex items-center gap-4">
             <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-sm font-medium px-4 py-2 rounded-lg border border-gray-700 transition-colors flex items-center gap-2">
                <Upload className="w-4 h-4" />
                <span>Upload Image</span>
                <input type="file" accept="image/*" onChange={handleFileUpload} className="hidden" />
              </label>
              {currentImage && (
                <button 
                  onClick={handleDownload}
                  className="bg-blue-600 hover:bg-blue-500 text-white text-sm font-medium px-4 py-2 rounded-lg transition-colors flex items-center gap-2"
                >
                  <Download className="w-4 h-4" />
                  <span>Download</span>
                </button>
              )}
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-8">

        {error && (
          <div className="mb-6 bg-red-900/20 border border-red-800 text-red-300 p-4 rounded-xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
            <AlertCircle className="w-5 h-5 flex-shrink-0" />
            <p>{error}</p>
          </div>
        )}

        {/* Empty State */}
        {!originalImage ? (
          <div className="flex flex-col items-center justify-center min-h-[60vh] border-2 border-dashed border-gray-800 rounded-3xl bg-gray-900/50">
            <div className="w-20 h-20 bg-gray-800 rounded-full flex items-center justify-center mb-6">
              <Upload className="w-10 h-10 text-gray-500" />
            </div>
            <h2 className="text-2xl font-semibold text-gray-300 mb-2">Start creating magic</h2>
            <p className="text-gray-500 mb-8">Upload an image to begin editing with Gemini AI</p>
            <label className="cursor-pointer bg-blue-600 hover:bg-blue-500 text-white font-semibold px-8 py-3 rounded-full transition-all shadow-lg hover:shadow-blue-500/25 flex items-center gap-2">
              <Upload className="w-5 h-5" />
              <span>Choose a File</span>
              <input type="file" accept="image/*" onChange={handleFileUpload} className="hidden" />
            </label>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">

            {/* Left Column: Canvas & Gallery */}
            <div className="lg:col-span-8 space-y-8">
              {/* Main Canvas Area */}
              <div className="bg-[#161b22] rounded-2xl p-1 shadow-2xl border border-gray-800 aspect-[4/3] relative group">
                 {processing.isProcessing && (
                   <div className="absolute inset-0 z-20 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center rounded-2xl">
                     <div className="relative">
                       <div className="w-16 h-16 border-4 border-blue-500/30 border-t-blue-500 rounded-full animate-spin"></div>
                       <Sparkles className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-blue-400 w-6 h-6 animate-pulse" />
                     </div>
                     <p className="mt-4 text-blue-200 font-medium animate-pulse">{processing.statusMessage}</p>
                   </div>
                 )}

                 <BeforeAfterSlider 
                    originalImage={originalImage} 
                    modifiedImage={currentImage || originalImage} 
                  />
              </div>

              {/* Gallery Below Preview */}
              <Gallery 
                images={history} 
                onSelect={handleHistorySelect} 
                selectedId={history.find(h => h.dataUrl === currentImage)?.id}
              />
            </div>

            {/* Right Column: Tools */}
            <div className="lg:col-span-4 space-y-6">
              <div className="sticky top-24">
                <div className="bg-[#161b22] border border-gray-800 rounded-2xl p-6 shadow-xl">
                  <h2 className="text-lg font-bold text-white mb-4">Quick Actions</h2>
                  <QuickActions 
                    onAction={handleTransform} 
                    disabled={processing.isProcessing} 
                  />

                  <div className="my-6 border-t border-gray-800"></div>

                  <TransformationPanel 
                    onTransform={handleTransform} 
                    isProcessing={processing.isProcessing} 
                  />
                </div>

                {/* Instructions / Tips */}
                <div className="mt-6 p-4 bg-blue-900/10 border border-blue-900/30 rounded-xl">
                  <h4 className="text-blue-400 text-sm font-semibold mb-2">Pro Tip</h4>
                  <p className="text-blue-300/80 text-xs leading-relaxed">
                    Use the slider to compare your changes. You can chain multiple edits by applying new transformations to the result!
                  </p>
                </div>
              </div>
            </div>

          </div>
        )}
      </main>
    </div>
  );
}

