import { GeneratedImage, ProcessingState } from './types';

export default function App() {
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [currentImage, setCurrentImage] = useState<string | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [processing, setProcessing] = useState<ProcessingState>({ isProcessing: false });
  const [error, setError] = useState<string | null>(null);

  // Load sample image on mount if none selected
  useEffect(() => {
    // Placeholder to make the UI look populated initially if desired
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const result = event.target?.result as string;
      setOriginalImage(result);
      setCurrentImage(result); // Reset current to original
      setError(null);
    };
    reader.readAsDataURL(file);
  };

  const handleGenerateStreet = async () => {
    setProcessing({ isProcessing: true, statusMessage: 'Generating urban scene...' });
    setError(null);
    try {
      const prompt = "A photorealistic eye-level shot of a busy modern city street in daytime. Concrete buildings, asphalt road, urban atmosphere, 4k quality.";
