import { GoogleGenAI } from "@google/genai";

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables");
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Generates an image from a text prompt using Gemini 3 Pro Image Preview with Search Grounding.
 * @param prompt The description of the image to generate.
 * @returns The generated image as a base64 string.
 */
export const generateImage = async (prompt: string): Promise<string> => {
  const ai = getAiClient();

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // Upgraded to Pro for Search Grounding
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        tools: [{ googleSearch: {} }], // Enable Google Search to find real location visuals
        // imageConfig: { imageSize: '1K' } // Defaulting to 1K for speed/stability
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data returned from Gemini.");
  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

/**
 * Transforms an image using Gemini 2.5 Flash Image model.
 * @param imageBase64 The base64 string of the image (without prefix usually, but we handle cleaning).
 * @param prompt The transformation instruction.
 * @returns The transformed image as a base64 string.
 */
export const transformImage = async (imageBase64: string, prompt: string): Promise<string> => {
  const ai = getAiClient();

  // Clean base64 string if it contains metadata prefix
  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Good balance of speed and editing capability
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/png', // Assume PNG or generally compatible type for upload
              data: cleanBase64,
            },
          },
          {
            text: `Edit this image: ${prompt}. Return only the edited image.`,
          },
        ],
      },
      // Note: nano banana models (flash-image) do not support responseMimeType or schemas nicely for images yet in all contexts,
      // but generateContent with image output is standard.
    });

    // Extract image from response
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data returned from Gemini.");

  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

