  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Check API Key on mount
  useEffect(() => {
    const checkApiKey = async () => {
      const win = window as any;
      if (win.aistudio) {
        const hasKey = await win.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        // Fallback for dev environments outside AI Studio
        setHasApiKey(true);
      }
    };
    checkApiKey();
  }, []);

  const handleConnectApiKey = async () => {
    const win = window as any;
    if (win.aistudio) {
      await win.aistudio.openSelectKey();
      // Assume success to avoid race condition
      setHasApiKey(true);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const result = event.target?.result as string;
      setOriginalImage(result);
      setCurrentImage(result); // Reset current to original
      setError(null);
      setSearchQuery(''); // Clear search query on upload
    };
    reader.readAsDataURL(file);
  };

  const handleSearch = async (query: string) => {
    if (!query.trim()) return;

    // Update input to match what's being searched (useful for chips)
    setSearchQuery(query);

    setProcessing({ isProcessing: true, statusMessage: `Searching visual data for ${query}...` });
    setError(null);
    try {
      // Prompt optimized for Gemini 3 Pro with Search Grounding
      // We explicitly ask to use the search results for accuracy
      const prompt = `A highly detailed, photorealistic street view image of ${query} in Berlin, Germany. Use Google Search to ensure the visual appearance matches the real location. 4k resolution, daylight, eye-level perspective.`;
      const generatedBase64 = await generateImage(prompt);

      setOriginalImage(generatedBase64);
      setCurrentImage(generatedBase64);

      const newImageEntry: GeneratedImage = {
        id: Date.now().toString(),
        dataUrl: generatedBase64,
        prompt: `Berlin: ${query}`,
        timestamp: Date.now(),
      };
      setHistory([newImageEntry]);

    } catch (err: any) {
      setError(err.message || "Failed to generate street image. Please try again.");
    } finally {
      setProcessing({ isProcessing: false });
    }
  };

