    }
  } catch (error) {
    // If search fails (e.g. 403), log warning but proceed with original prompt
    console.warn("Search grounding failed or not permitted, using original prompt.", error);
  }

  // Step 2: Generate image using the standard image model
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Standard model, widely available
      contents: {
        parts: [{ text: enhancedPrompt }],
      },
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

