import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Eraser, Paintbrush, Move } from 'lucide-react';

interface InpaintCanvasProps {
  image: string;
  onMaskChange: (maskBase64: string | null) => void;
  brushSize: number;
  isEditMode: boolean;
}

export const InpaintCanvas: React.FC<InpaintCanvasProps> = ({ 
  image, 
  onMaskChange, 
  brushSize,
  isEditMode 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCanvasRef = useRef<HTMLCanvasElement>(null);
  const maskCanvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);

  // Initialize canvases
  useEffect(() => {
    const img = new Image();
    img.src = image;
    img.onload = () => {
      const imgCanvas = imageCanvasRef.current;
      const mskCanvas = maskCanvasRef.current;
      if (!imgCanvas || !mskCanvas) return;

      const displayWidth = containerRef.current?.clientWidth || 800;
      const scale = displayWidth / img.width;
      const displayHeight = img.height * scale;

      imgCanvas.width = img.width;
      imgCanvas.height = img.height;
      mskCanvas.width = img.width;
      mskCanvas.height = img.height;

      const ctx = imgCanvas.getContext('2d');
      ctx?.drawImage(img, 0, 0);

      // Clear mask
      const mctx = mskCanvas.getContext('2d');
      if (mctx) {
        mctx.fillStyle = 'black';
        mctx.fillRect(0, 0, mskCanvas.width, mskCanvas.height);
      }
    };
  }, [image]);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = maskCanvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    let clientX, clientY;
    if ('touches' in e) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else {
      clientX = e.clientX;
      clientY = e.clientY;
    }

    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY
    };
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing || !isEditMode) return;
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;

    const { x, y } = getCoordinates(e);

    ctx.strokeStyle = 'rgba(255, 0, 0, 0.5)';
    ctx.lineWidth = brushSize * (canvas.width / 800); // Scale brush to actual resolution
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.globalCompositeOperation = 'source-over';

    // For the actual mask we send to API, we might want white on black
    // But for UI feedback, we show semi-transparent red
    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    setIsDrawing(false);
    const canvas = maskCanvasRef.current;
    if (canvas) {
      // Create a clean BW mask for the API
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = canvas.width;
      tempCanvas.height = canvas.height;
      const tctx = tempCanvas.getContext('2d');
      if (tctx) {
        tctx.fillStyle = 'black';
        tctx.fillRect(0, 0, canvas.width, canvas.height);
        tctx.drawImage(canvas, 0, 0);
        // We need to ensure the "red" strokes become white for the AI
        const imageData = tctx.getImageData(0, 0, tempCanvas.width, tempCanvas.height);
        for (let i = 0; i < imageData.data.length; i += 4) {
          if (imageData.data[i] > 0) { // If there's red
            imageData.data[i] = 255;
            imageData.data[i+1] = 255;
            imageData.data[i+2] = 255;
          }
        }
        tctx.putImageData(imageData, 0, 0);
        onMaskChange(tempCanvas.toDataURL('image/png'));
      }
    }
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isEditMode) return;
    setIsDrawing(true);
    const ctx = maskCanvasRef.current?.getContext('2d');
    if (ctx) {
      const { x, y } = getCoordinates(e);
      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const clearMask = () => {
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && canvas) {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      onMaskChange(null);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full aspect-[4/3] bg-black rounded-xl overflow-hidden cursor-crosshair">
      <canvas ref={imageCanvasRef} className="absolute inset-0 w-full h-full object-contain" />
      <canvas 
        ref={maskCanvasRef} 
        className="absolute inset-0 w-full h-full object-contain opacity-60"
        onMouseDown={startDrawing}
        onMouseMove={draw}
        onMouseUp={stopDrawing}
        onMouseLeave={stopDrawing}
        onTouchStart={startDrawing}
        onTouchMove={draw}
        onTouchEnd={stopDrawing}
      />

      {isEditMode && (
        <div className="absolute top-4 left-4 flex gap-2">
          <button 
            onClick={clearMask}
            className="bg-gray-900/80 hover:bg-gray-800 text-white text-xs px-3 py-1.5 rounded-lg border border-gray-700 backdrop-blur-md transition-colors"
          >
            Clear Mask
          </button>
        </div>
      )}

      {!isEditMode && (
        <div className="absolute inset-0 bg-transparent flex items-center justify-center pointer-events-none">
          <div className="bg-blue-600/20 text-blue-400 px-4 py-2 rounded-full border border-blue-500/30 backdrop-blur-md text-sm font-medium">
             Comparison View
          </div>
        </div>
      )}
    </div>
  );
};

