import React, { useRef, useState, useEffect, useCallback } from 'react';

interface InpaintCanvasProps {
  image: string;
  onMaskChange: (maskBase64: string | null) => void;
  brushSize: number;
  isEditMode: boolean;
}

export const InpaintCanvas: React.FC<InpaintCanvasProps> = ({ 
  image, 
  onMaskChange, 
  brushSize,
  isEditMode 
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCanvasRef = useRef<HTMLCanvasElement>(null);
  const maskCanvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);

  const initCanvases = useCallback(() => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = image;
    img.onload = () => {
      const imgCanvas = imageCanvasRef.current;
      const mskCanvas = maskCanvasRef.current;
      if (!imgCanvas || !mskCanvas) return;

      // Use actual image dimensions to maintain quality
      imgCanvas.width = img.width;
      imgCanvas.height = img.height;
      mskCanvas.width = img.width;
      mskCanvas.height = img.height;

      const ctx = imgCanvas.getContext('2d');
      ctx?.drawImage(img, 0, 0);

      // Clear mask to black (black = keep, white = change)
      const mctx = mskCanvas.getContext('2d');
      if (mctx) {
        mctx.fillStyle = 'black';
        mctx.fillRect(0, 0, mskCanvas.width, mskCanvas.height);
      }
    };
  }, [image]);

  useEffect(() => {
    initCanvases();
  }, [initCanvases]);

  const getCoordinates = (e: any) => {
    const canvas = maskCanvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    const clientX = e.clientX || (e.touches && e.touches[0].clientX);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY);

    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY
    };
  };

  const draw = (e: any) => {
    if (!isDrawing || !isEditMode) return;
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;

    const { x, y } = getCoordinates(e);

    // Brush styling
    ctx.strokeStyle = 'white'; // White for mask area to be edited
    ctx.lineWidth = brushSize * (canvas.width / 1000); 
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    setIsDrawing(false);
    const canvas = maskCanvasRef.current;
    if (canvas) {
      onMaskChange(canvas.toDataURL('image/png'));
    }
  };

  const startDrawing = (e: any) => {
    if (!isEditMode) return;
    setIsDrawing(true);
    const ctx = maskCanvasRef.current?.getContext('2d');
    if (ctx) {
      const { x, y } = getCoordinates(e);
      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const clearMask = () => {
    const canvas = maskCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && canvas) {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      onMaskChange(null);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full h-full bg-black flex items-center justify-center">
      <div className="relative w-full h-full">
        <canvas ref={imageCanvasRef} className="absolute inset-0 w-full h-full object-contain" />
        <canvas 
          ref={maskCanvasRef} 
          className="absolute inset-0 w-full h-full object-contain cursor-crosshair mix-blend-screen opacity-70"
          style={{ filter: 'drop-shadow(0 0 5px rgba(255,255,255,0.5))' }}
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
        />

        <div className="absolute top-6 left-6 flex items-center gap-3">
          <button 
            onClick={clearMask}
            className="bg-gray-950/90 hover:bg-gray-900 text-white text-[10px] font-black uppercase tracking-widest px-4 py-2 rounded-xl border border-gray-800 backdrop-blur-xl transition-all shadow-2xl hover:border-blue-500/50"
          >
            Clear Brush
          </button>
          <div className="bg-blue-600 px-3 py-1.5 rounded-lg shadow-lg text-[10px] font-black uppercase tracking-widest text-white animate-pulse">
            Drawing Mode
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Eraser, RotateCcw, Palette } from 'lucide-react';

interface InpaintCanvasProps {
  image: string;
  onOverlayChange: (data: { mask?: string; sketch?: string } | null) => void;
  brushSize: number;
  mode: 'mask' | 'sketch';
}

const COLORS = [
  '#ffffff', // White (for mask)
  '#ef4444', // Red
  '#3b82f6', // Blue
  '#10b981', // Green
  '#f59e0b', // Amber
  '#a855f7', // Purple
  '#000000', // Black
];

export const InpaintCanvas: React.FC<InpaintCanvasProps> = ({ 
  image, 
  onOverlayChange, 
  brushSize,
  mode
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCanvasRef = useRef<HTMLCanvasElement>(null);
  const drawingCanvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [selectedColor, setSelectedColor] = useState(mode === 'mask' ? '#ffffff' : '#ef4444');

  useEffect(() => {
    if (mode === 'mask') setSelectedColor('#ffffff');
  }, [mode]);

  const initCanvases = useCallback(() => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = image;
    img.onload = () => {
      const imgCanvas = imageCanvasRef.current;
      const drwCanvas = drawingCanvasRef.current;
      if (!imgCanvas || !drwCanvas) return;

      imgCanvas.width = img.width;
      imgCanvas.height = img.height;
      drwCanvas.width = img.width;
      drwCanvas.height = img.height;

      const ctx = imgCanvas.getContext('2d');
      ctx?.drawImage(img, 0, 0);

      // We don't fill with black anymore, we start transparent
      const dctx = drwCanvas.getContext('2d');
      dctx?.clearRect(0, 0, drwCanvas.width, drwCanvas.height);
    };
  }, [image]);

  useEffect(() => {
    initCanvases();
  }, [initCanvases]);

  const getCoordinates = (e: any) => {
    const canvas = drawingCanvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;

    const clientX = e.clientX || (e.touches && e.touches[0].clientX);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY);

    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY
    };
  };

  const draw = (e: any) => {
    if (!isDrawing) return;
    const canvas = drawingCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;

    const { x, y } = getCoordinates(e);

    ctx.strokeStyle = selectedColor;
    ctx.lineWidth = brushSize * (canvas.width / 1000); 
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    setIsDrawing(false);
    const canvas = drawingCanvasRef.current;
    if (canvas) {
      if (mode === 'mask') {
        // For mask, we need white on black
        const maskCanvas = document.createElement('canvas');
        maskCanvas.width = canvas.width;
        maskCanvas.height = canvas.height;
        const mctx = maskCanvas.getContext('2d');
        if (mctx) {
          mctx.fillStyle = 'black';
          mctx.fillRect(0, 0, maskCanvas.width, maskCanvas.height);
          mctx.drawImage(canvas, 0, 0);
          onOverlayChange({ mask: maskCanvas.toDataURL('image/png') });
        }
      } else {
        // For sketch, we send the drawing on black
        const sketchCanvas = document.createElement('canvas');
        sketchCanvas.width = canvas.width;
        sketchCanvas.height = canvas.height;
        const sctx = sketchCanvas.getContext('2d');
        if (sctx) {
          sctx.fillStyle = 'black';
          sctx.fillRect(0, 0, sketchCanvas.width, sketchCanvas.height);
          sctx.drawImage(canvas, 0, 0);
          onOverlayChange({ sketch: sketchCanvas.toDataURL('image/png') });
        }
      }
    }
  };

  const startDrawing = (e: any) => {
    setIsDrawing(true);
    const ctx = drawingCanvasRef.current?.getContext('2d');
    if (ctx) {
      const { x, y } = getCoordinates(e);
      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const clearCanvas = () => {
    const canvas = drawingCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && canvas) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      onOverlayChange(null);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full h-full bg-black flex items-center justify-center">
      <div className="relative w-full h-full">
        <canvas ref={imageCanvasRef} className="absolute inset-0 w-full h-full object-contain" />
        <canvas 
          ref={drawingCanvasRef} 
          className="absolute inset-0 w-full h-full object-contain cursor-crosshair z-10"
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
        />

        {/* Toolbar Overlay */}
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-gray-950/80 backdrop-blur-xl px-4 py-3 rounded-2xl border border-gray-800 shadow-2xl z-20">
          <div className="flex items-center gap-2 border-r border-gray-800 pr-4">
            <button 
              onClick={clearCanvas}
              title="Clear Drawing"
              className="p-2 hover:bg-gray-800 rounded-lg text-gray-400 hover:text-white transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          </div>

          {mode === 'sketch' && (
            <div className="flex items-center gap-2">
              <Palette className="w-4 h-4 text-gray-500 mr-1" />
              {COLORS.map(color => (
                <button
                  key={color}
                  onClick={() => setSelectedColor(color)}
                  className={`w-6 h-6 rounded-full border-2 transition-transform ${selectedColor === color ? 'border-white scale-125' : 'border-transparent hover:scale-110'}`}
                  style={{ backgroundColor: color }}
                />
              ))}
            </div>
          )}

          {mode === 'mask' && (
            <div className="flex items-center gap-2 text-xs font-bold text-white uppercase tracking-wider px-2">
              <div className="w-4 h-4 rounded-full bg-white mr-2" />
              Masking Tool
            </div>
          )}
        </div>

        <div className="absolute top-6 left-6 z-20">
          <div className="bg-blue-600 px-3 py-1.5 rounded-lg shadow-lg text-[10px] font-black uppercase tracking-widest text-white animate-pulse">
            {mode === 'sketch' ? 'Sketch Mode' : 'Mask Mode'}
          </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables");
  }
  return new GoogleGenAI({ apiKey });
};

/**
 * Uses Gemini 2.5 Flash to get grounded descriptive details about a location.
 */
export const getGroundedPrompt = async (prompt: string): Promise<string> => {
  const ai = getAiClient();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite-latest",
      contents: `Search for current visual details of "${prompt}" in Berlin. 
      Provide a highly detailed, photorealistic visual description for an AI image generator. 
      Focus on architecture, street furniture, foliage, and atmosphere. 
      Output ONLY the description.`,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });
    return response.text || prompt;
  } catch (error) {
    console.warn("Search grounding failed:", error);
    return prompt;
  }
};

/**
 * Generates a new image from scratch using the flash image model.
 */
export const generateImage = async (prompt: string): Promise<string> => {
  const ai = getAiClient();
  // Get grounded details first
  const detailedPrompt = await getGroundedPrompt(prompt);

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: detailedPrompt }],
      },
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData?.data) {
      return `data:image/png;base64,${imagePart.inlineData.data}`;
    }
    throw new Error("The model did not return an image.");
  } catch (error: any) {
    console.error("Image Generation Error:", error);
    if (error.message?.includes("403") || error.message?.includes("permission")) {
      throw new Error("Access denied to image generation model. Please ensure your API key has necessary permissions for Gemini 2.5 Flash Image.");
    }
    throw error;
  }
};

/**
 * Transforms an existing image, optionally using a mask for inpainting or a sketch for visual guidance.
 */
export const transformImage = async (
  imageBase64: string, 
  prompt: string, 
  maskBase64?: string | null,
  sketchBase64?: string | null
): Promise<string> => {
  const ai = getAiClient();
  const cleanImage = imageBase64.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');

  const parts: any[] = [
    {
      inlineData: {
        mimeType: 'image/png',
        data: cleanImage,
      },
    }
  ];

  if (sketchBase64) {
    const cleanSketch = sketchBase64.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');
    parts.push({
      inlineData: {
        mimeType: 'image/png',
        data: cleanSketch,
      }
    });
    parts.push({
      text: `Incorporate the sketched object from the second image into the scene shown in the first image at the corresponding location. The sketch represents: ${prompt}. Make it look like a photorealistic integrated part of the urban environment.`,
    });
  } else if (maskBase64) {
    const cleanMask = maskBase64.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');
    parts.push({
      inlineData: {
        mimeType: 'image/png',
        data: cleanMask,
      }
    });
    parts.push({
      text: `Inpaint the area marked by the white mask in the second image. Instruction: ${prompt}. Keep everything else exactly the same.`,
    });
  } else {
    parts.push({
      text: `Transform this image based on the following instruction: ${prompt}. Maintain the original scene structure and perspective.`,
    });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
    });

    const imagePart = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    if (imagePart?.inlineData?.data) {
      return `data:image/png;base64,${imagePart.inlineData.data}`;
    }
    throw new Error("No image was returned from the transformation.");
  } catch (error: any) {
    console.error("Transformation Error:", error);
    throw error;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  Upload, AlertCircle, Sparkles, Download, Building2, 
  History, RotateCcw, Search, MousePointer2, Paintbrush2, 
  Sliders, Wand2, Pencil
} from 'lucide-react';
import { BeforeAfterSlider } from './components/BeforeAfterSlider';
import { InpaintCanvas } from './components/InpaintCanvas';
import { QuickActions } from './components/QuickActions';
import { TransformationPanel } from './components/TransformationPanel';
import { transformImage, generateImage } from './services/geminiService';
import { GeneratedImage, ProcessingState } from './types';

export default function App() {
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [currentImage, setCurrentImage] = useState<string | null>(null);
  const [history, setHistory] = useState<GeneratedImage[]>([]);
  const [processing, setProcessing] = useState<ProcessingState>({ isProcessing: false });
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Editor States
  const [editMode, setEditMode] = useState<'comparison' | 'mask' | 'sketch'>('comparison');
  const [maskBase64, setMaskBase64] = useState<string | null>(null);
  const [sketchBase64, setSketchBase64] = useState<string | null>(null);
  const [brushSize, setBrushSize] = useState(40);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const result = event.target?.result as string;
      setOriginalImage(result);
      setCurrentImage(result);
      setError(null);
      setHistory([{ id: 'original', dataUrl: result, prompt: 'Original Upload', timestamp: Date.now() }]);
      setEditMode('comparison');
    };
    reader.readAsDataURL(file);
  };

  const handleSearch = async (query: string) => {
    if (!query.trim()) return;
    setSearchQuery(query);
    setProcessing({ isProcessing: true, statusMessage: `Visualizing ${query} with Google Search...` });
    setError(null);
    try {
      const generatedBase64 = await generateImage(query);
      setOriginalImage(generatedBase64);
      setCurrentImage(generatedBase64);
      setHistory([{ id: Date.now().toString(), dataUrl: generatedBase64, prompt: `Search: ${query}`, timestamp: Date.now() }]);
      setEditMode('comparison');
    } catch (err: any) {
      setError(err.message || "Failed to generate street image.");
    } finally {
      setProcessing({ isProcessing: false });
    }
  };

  const handleTransform = async (prompt: string) => {
    if (!currentImage) return;
    setProcessing({ isProcessing: true, statusMessage: 'Synthesizing urban changes...' });
    setError(null);

    try {
      const newImageData = await transformImage(
        currentImage, 
        prompt, 
        editMode === 'mask' ? maskBase64 : null,
        editMode === 'sketch' ? sketchBase64 : null
      );

      const newImageEntry: GeneratedImage = {
        id: Date.now().toString(),
        dataUrl: newImageData,
        prompt: editMode !== 'comparison' ? `${editMode === 'sketch' ? 'Sketch' : 'Area'}: ${prompt}` : prompt,
        timestamp: Date.now(),
      };

      setHistory((prev) => [newImageEntry, ...prev]);
      setCurrentImage(newImageData);

      // Reset tools
      setEditMode('comparison');
      setMaskBase64(null);
      setSketchBase64(null);
    } catch (err: any) {
      setError(err.message || "Failed to transform image");
    } finally {
      setProcessing({ isProcessing: false });
    }
  };

  const handleOverlayChange = (data: { mask?: string; sketch?: string } | null) => {
    if (!data) {
      setMaskBase64(null);
