import React, { useRef, useState, useEffect, useCallback } from 'react';
import { RotateCcw, Palette, MousePointer2 } from 'lucide-react';

interface InpaintCanvasProps {
  image: string;
  onOverlayChange: (data: { mask?: string; sketch?: string; assetPrompt?: string } | null) => void;
  brushSize: number;
  mode: 'mask' | 'sketch' | 'asset';
  selectedAsset?: { id: string, name: string, prompt: string };
}

const COLORS = [
  '#ffffff', '#ef4444', '#3b82f6', '#10b981', '#f59e0b', '#a855f7', '#000000',
];

export const InpaintCanvas: React.FC<InpaintCanvasProps> = ({ 
  image, 
  onOverlayChange, 
  brushSize,
  mode,
  selectedAsset
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCanvasRef = useRef<HTMLCanvasElement>(null);
  const drawingCanvasRef = useRef<HTMLCanvasElement>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [selectedColor, setSelectedColor] = useState('#ffffff');

  useEffect(() => {
    if (mode === 'mask') setSelectedColor('#ffffff');
    if (mode === 'sketch' && selectedColor === '#ffffff') setSelectedColor('#ef4444');
  }, [mode, selectedColor]);

  const initCanvases = useCallback(() => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.src = image;
    img.onload = () => {
      const imgCanvas = imageCanvasRef.current;
      const drwCanvas = drawingCanvasRef.current;
      if (!imgCanvas || !drwCanvas) return;

      imgCanvas.width = img.width;
      imgCanvas.height = img.height;
      drwCanvas.width = img.width;
      drwCanvas.height = img.height;

      const ctx = imgCanvas.getContext('2d');
      ctx?.drawImage(img, 0, 0);

      const dctx = drwCanvas.getContext('2d');
      dctx?.clearRect(0, 0, drwCanvas.width, drwCanvas.height);
    };
  }, [image]);

  useEffect(() => {
    initCanvases();
  }, [initCanvases]);

  const getCoordinates = (e: any) => {
    const canvas = drawingCanvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const clientX = e.clientX || (e.touches && e.touches[0].clientX);
    const clientY = e.clientY || (e.touches && e.touches[0].clientY);
    return { x: (clientX - rect.left) * scaleX, y: (clientY - rect.top) * scaleY };
  };

  const draw = (e: any) => {
    if (!isDrawing || mode === 'asset') return;
    const canvas = drawingCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;

    const { x, y } = getCoordinates(e);
    ctx.strokeStyle = selectedColor;
    ctx.lineWidth = brushSize * (canvas.width / 1000); 
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.lineTo(x, y);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(x, y);
  };

  const handleAssetPlacement = (e: any) => {
    if (mode !== 'asset' || !selectedAsset) return;
    const canvas = drawingCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (!canvas || !ctx) return;

    const { x, y } = getCoordinates(e);

    // Draw a placeholder marker for the asset
    ctx.fillStyle = 'rgba(59, 130, 246, 0.8)';
    const size = brushSize * (canvas.width / 500);
    ctx.beginPath();
    ctx.arc(x, y, size / 2, 0, Math.PI * 2);
    ctx.fill();

    // Also draw a label
    ctx.fillStyle = 'white';
    ctx.font = `${size / 2}px Inter, sans-serif`;
    ctx.textAlign = 'center';
    ctx.fillText(selectedAsset.name, x, y - size/1.5);

    updateOverlays();
  };

  const updateOverlays = () => {
    const canvas = drawingCanvasRef.current;
    if (!canvas) return;

    if (mode === 'mask') {
      const maskCanvas = document.createElement('canvas');
      maskCanvas.width = canvas.width;
      maskCanvas.height = canvas.height;
      const mctx = maskCanvas.getContext('2d');
      if (mctx) {
        mctx.fillStyle = 'black';
        mctx.fillRect(0, 0, maskCanvas.width, maskCanvas.height);
        mctx.drawImage(canvas, 0, 0);
        onOverlayChange({ mask: maskCanvas.toDataURL('image/png') });
      }
    } else {
      const sketchCanvas = document.createElement('canvas');
      sketchCanvas.width = canvas.width;
      sketchCanvas.height = canvas.height;
      const sctx = sketchCanvas.getContext('2d');
      if (sctx) {
        sctx.fillStyle = 'black';
        sctx.fillRect(0, 0, sketchCanvas.width, sketchCanvas.height);
        sctx.drawImage(canvas, 0, 0);
        onOverlayChange({ 
          sketch: sketchCanvas.toDataURL('image/png'),
          assetPrompt: mode === 'asset' ? selectedAsset?.prompt : undefined
        });
      }
    }
  };

  const stopDrawing = () => {
    if (!isDrawing) return;
    setIsDrawing(false);
    updateOverlays();
  };

  const startDrawing = (e: any) => {
    if (mode === 'asset') {
      handleAssetPlacement(e);
      return;
    }
    setIsDrawing(true);
    const ctx = drawingCanvasRef.current?.getContext('2d');
    if (ctx) {
      const { x, y } = getCoordinates(e);
      ctx.beginPath();
      ctx.moveTo(x, y);
    }
  };

  const clearCanvas = () => {
    const canvas = drawingCanvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && canvas) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      onOverlayChange(null);
    }
  };

  return (
    <div ref={containerRef} className="relative w-full h-full bg-black flex items-center justify-center">
      <div className="relative w-full h-full">
        <canvas ref={imageCanvasRef} className="absolute inset-0 w-full h-full object-contain" />
        <canvas 
          ref={drawingCanvasRef} 
          className="absolute inset-0 w-full h-full object-contain cursor-crosshair z-10"
          onMouseDown={startDrawing}
          onMouseMove={draw}
          onMouseUp={stopDrawing}
          onMouseLeave={stopDrawing}
          onTouchStart={startDrawing}
          onTouchMove={draw}
          onTouchEnd={stopDrawing}
        />

        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-gray-950/80 backdrop-blur-xl px-4 py-3 rounded-2xl border border-gray-800 shadow-2xl z-20">
          <button onClick={clearCanvas} className="p-2 hover:bg-gray-800 rounded-lg text-gray-400 hover:text-white transition-colors">
            <RotateCcw className="w-4 h-4" />
          </button>

          {mode === 'sketch' && (
            <div className="flex items-center gap-2 border-l border-gray-800 pl-4">
              <Palette className="w-4 h-4 text-gray-500 mr-1" />
              {COLORS.map(color => (
                <button key={color} onClick={() => setSelectedColor(color)}
                  className={`w-6 h-6 rounded-full border-2 transition-transform ${selectedColor === color ? 'border-white scale-125' : 'border-transparent hover:scale-110'}`}
                  style={{ backgroundColor: color }}
                />
              ))}
            </div>
          )}

          {mode === 'asset' && selectedAsset && (
            <div className="flex items-center gap-3 border-l border-gray-800 pl-4">
              <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" />
              <span className="text-xs font-black text-white uppercase tracking-wider">
                Placing: {selectedAsset.name}
              </span>
              <MousePointer2 className="w-4 h-4 text-blue-400" />
            </div>
          )}

          {mode === 'mask' && (
            <div className="flex items-center gap-2 text-xs font-bold text-white uppercase tracking-wider px-2 border-l border-gray-800 pl-4">
              <div className="w-3 h-3 rounded-sm bg-white mr-1" />
              Mask Tool
            </div>
          )}
        </div>

        <div className="absolute top-6 left-6 z-20">
          <div className="bg-blue-600 px-3 py-1.5 rounded-lg shadow-lg text-[10px] font-black uppercase tracking-widest text-white">
            {mode === 'sketch' ? 'Sketch' : mode === 'mask' ? 'Mask' : 'Placement'}
          </div>
        </div>
      </div>
    </div>
  );
};

