  // Editor States
  const [editMode, setEditMode] = useState<'comparison' | 'mask' | 'sketch' | 'asset'>('comparison');
  const [maskBase64, setMaskBase64] = useState<string | null>(null);
  const [sketchBase64, setSketchBase64] = useState<string | null>(null);
  const [assetPrompt, setAssetPrompt] = useState<string | null>(null);
  const [brushSize, setBrushSize] = useState(40);
  const [selectedAsset, setSelectedAsset] = useState<any>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const result = event.target?.result as string;
      setOriginalImage(result);
      setCurrentImage(result);
      setError(null);
      setHistory([{ id: 'original', dataUrl: result, prompt: 'Original Upload', timestamp: Date.now() }]);
      setEditMode('comparison');
    };
    reader.readAsDataURL(file);
  };

  const handleSearch = async (query: string) => {
    if (!query.trim()) return;
    setSearchQuery(query);
    setProcessing({ isProcessing: true, statusMessage: `Visualizing ${query} with Google Search...` });
    setError(null);
    try {
      const generatedBase64 = await generateImage(query);
      setOriginalImage(generatedBase64);
      setCurrentImage(generatedBase64);
      setHistory([{ id: Date.now().toString(), dataUrl: generatedBase64, prompt: `Search: ${query}`, timestamp: Date.now() }]);
      setEditMode('comparison');
    } catch (err: any) {
      setError(err.message || "Failed to generate street image.");
    } finally {
      setProcessing({ isProcessing: false });
    }
  };

  const handleTransform = async (prompt: string) => {
    if (!currentImage) return;

    // If in asset mode but no asset prompt generated yet, warn
    const finalPrompt = editMode === 'asset' ? (assetPrompt ? `Add ${assetPrompt}` : prompt) : prompt;

    setProcessing({ isProcessing: true, statusMessage: 'Synthesizing changes...' });
    setError(null);

    try {
      const newImageData = await transformImage(
        currentImage, 
        finalPrompt, 
        editMode === 'mask' ? maskBase64 : null,
        (editMode === 'sketch' || editMode === 'asset') ? sketchBase64 : null
      );

      const label = editMode === 'asset' ? `Asset: ${selectedAsset?.name || 'Item'}` : (editMode === 'sketch' ? 'Sketch' : 'Area');
      const newImageEntry: GeneratedImage = {
        id: Date.now().toString(),
        dataUrl: newImageData,
        prompt: editMode !== 'comparison' ? `${label}: ${prompt}` : prompt,
        timestamp: Date.now(),
      };

      setHistory((prev) => [newImageEntry, ...prev]);
      setCurrentImage(newImageData);

      // Reset tools
      setEditMode('comparison');
      setMaskBase64(null);
      setSketchBase64(null);
      setAssetPrompt(null);
      setSelectedAsset(null);
    } catch (err: any) {
      setError(err.message || "Failed to transform image");
    } finally {
      setProcessing({ isProcessing: false });
    }
  };

  const handleOverlayChange = (data: { mask?: string; sketch?: string; assetPrompt?: string } | null) => {
    if (!data) {
      setMaskBase64(null);
      setSketchBase64(null);
      setAssetPrompt(null);
    } else {
      if (data.mask) setMaskBase64(data.mask);
      if (data.sketch) setSketchBase64(data.sketch);
      if (data.assetPrompt) setAssetPrompt(data.assetPrompt);
    }
  };

  const handleAssetSelect = (asset: any) => {
    setSelectedAsset(asset);
    setEditMode('asset');
  };

  return (
    <div className="min-h-screen bg-[#0d1117] text-gray-200 font-sans">
      <header className="border-b border-gray-800 bg-[#161b22]/90 backdrop-blur-md sticky top-0 z-50">
        <div className="max-w-[1600px] mx-auto px-6 py-3 flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-blue-600 to-cyan-500 p-2 rounded-xl shadow-lg shadow-blue-500/20">
              <Building2 className="w-5 h-5 text-white" />
            </div>
            <div>
              <h1 className="text-lg font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-cyan-400">Urban Vision</h1>
              <span className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Berlin Transformation Lab</span>
            </div>
          </div>

          {originalImage && (
            <div className="flex items-center gap-1 bg-gray-950/50 p-1 rounded-xl border border-gray-800">
               <button onClick={() => setEditMode('comparison')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${editMode === 'comparison' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                 <MousePointer2 className="w-4 h-4" /> Compare
               </button>
               <button onClick={() => setEditMode('mask')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${editMode === 'mask' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                 <Paintbrush2 className="w-4 h-4" /> Mask
               </button>
               <button onClick={() => setEditMode('sketch')} className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all ${editMode === 'sketch' ? 'bg-blue-600 text-white shadow-md' : 'text-gray-500 hover:text-gray-300'}`}>
                 <Pencil className="w-4 h-4" /> Sketch
               </button>
            </div>
          )}

          <div className="flex items-center gap-3">
             <label className="cursor-pointer bg-gray-800 hover:bg-gray-700 text-gray-300 hover:text-white px-4 py-2 rounded-xl transition-all border border-gray-700 flex items-center gap-2 text-sm font-medium">
                <Upload className="w-4 h-4" /> <span className="hidden sm:inline">Upload</span>
                <input type="file" accept="image/*" onChange={handleFileUpload} className="hidden" />
             </label>
             {currentImage && (
                <button onClick={() => {
                  const a = document.createElement('a');
                  a.href = currentImage;
                  a.download = `urban-vision-${Date.now()}.png`;
                  a.click();
                }} className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-xl text-sm font-medium transition-all shadow-lg shadow-blue-900/40">
                  <Download className="w-4 h-4" />
                </button>
             )}
          </div>
        </div>
      </header>

      <main className="max-w-[1600px] mx-auto p-6">
        {!originalImage ? (
          <div className="flex flex-col items-center justify-center min-h-[75vh] border-2 border-dashed border-gray-800 rounded-[2.5rem] bg-gray-900/20 p-12 text-center group transition-all hover:bg-gray-900/30 hover:border-blue-500/30">
            <div className="w-24 h-24 bg-gray-800 rounded-3xl flex items-center justify-center mb-8 shadow-2xl ring-1 ring-gray-700 group-hover:ring-blue-500/50 transition-all">
              <Building2 className="w-12 h-12 text-blue-500" />
            </div>
            <h2 className="text-4xl font-black mb-4 tracking-tight">Reimagine Your Street</h2>
            <p className="text-gray-400 mb-10 max-w-lg text-lg">Search for a street in Berlin or upload your own photo to begin.</p>
            <form onSubmit={(e) => { e.preventDefault(); handleSearch(searchQuery); }} className="w-full max-w-2xl">
              <div className="relative group">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-500 group-focus-within:text-blue-500 transition-colors" />
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} placeholder="e.g. 'Friedrichstraße' or 'Alexanderplatz'" className="w-full bg-gray-800/80 border border-gray-700 rounded-[1.5rem] py-5 pl-14 pr-6 text-lg focus:ring-4 focus:ring-blue-500/20 focus:border-blue-500 outline-none transition-all shadow-2xl" disabled={processing.isProcessing} />
                <button type="submit" disabled={!searchQuery.trim() || processing.isProcessing} className="absolute right-3 top-1/2 -translate-y-1/2 bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-xl font-bold shadow-lg">GO</button>
              </div>
            </form>
          </div>
        ) : (
          <div className="grid grid-cols-12 gap-8 h-[calc(100vh-140px)]">
            <div className="col-span-12 lg:col-span-9 flex flex-col h-full gap-6 overflow-y-auto pr-1 custom-scrollbar">
              <div className="relative aspect-[4/3] bg-[#161b22] border border-gray-800 rounded-[2rem] p-1 shadow-2xl overflow-hidden flex items-center justify-center min-h-[400px]">
                 {processing.isProcessing && (
                   <div className="absolute inset-0 z-40 bg-gray-950/80 backdrop-blur-md flex flex-col items-center justify-center text-center p-8">
                     <div className="w-16 h-16 border-4 border-blue-500/20 border-t-blue-500 rounded-full animate-spin mb-6" />
                     <p className="text-xl font-bold text-white tracking-tight">{processing.statusMessage}</p>
                   </div>
                 )}

                 {editMode !== 'comparison' ? (
                   <InpaintCanvas 
                      image={currentImage || originalImage!} 
                      onOverlayChange={handleOverlayChange}
                      brushSize={brushSize}
                      mode={editMode}
                      selectedAsset={selectedAsset}
                   />
                 ) : (
                   <BeforeAfterSlider 
                      originalImage={originalImage!} 
                      modifiedImage={currentImage || originalImage!} 
                   />
                 )}
              </div>

              <div className="bg-[#161b22] border border-gray-800 p-8 rounded-[2rem] shadow-xl flex flex-col gap-8">
                <div className="flex items-center justify-between border-b border-gray-800 pb-4">
                  <h2 className="text-xl font-bold flex items-center gap-2">
                    <Wand2 className="w-5 h-5 text-blue-500" /> Transformation Toolkit
                  </h2>
                  <div className="flex items-center gap-4 bg-gray-950 px-4 py-2 rounded-xl border border-gray-800">
                    <div className="flex items-center gap-2 text-[10px] font-black text-gray-500 uppercase tracking-widest"><Sliders className="w-3 h-3"/> {editMode === 'asset' ? 'Scale' : 'Size'}</div>
                    <input type="range" min="10" max="150" value={brushSize} onChange={(e) => setBrushSize(parseInt(e.target.value))} className="w-32 accent-blue-500" />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                   <div className="space-y-4">
                      <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest flex items-center gap-2"><Package className="w-3 h-3 text-blue-500"/> Asset Library</h3>
                      <AssetLibrary onSelectAsset={handleAssetSelect} selectedAssetId={selectedAsset?.id} disabled={processing.isProcessing} />
                   </div>

                   <div className="space-y-4">
                      <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest">Presets</h3>
                      <QuickActions onAction={handleTransform} disabled={processing.isProcessing} />
                   </div>

                   <div className="space-y-4">
                      <h3 className="text-xs font-black text-gray-500 uppercase tracking-widest">Custom Command</h3>
                      <TransformationPanel 
                        onTransform={handleTransform} 
                        isProcessing={processing.isProcessing} 
                        placeholder={editMode === 'asset' ? "Describe the item (e.g. 'vintage wood', 'white cat')..." : "Describe the change..."}
                      />
                   </div>
                </div>
              </div>
            </div>

            <div className="hidden lg:flex lg:col-span-3 flex-col h-full bg-[#161b22] border border-gray-800 rounded-[2rem] p-6 shadow-xl overflow-hidden">
               <div className="flex items-center justify-between mb-6 px-2">
                 <h3 className="text-sm font-black text-gray-300 uppercase tracking-widest flex items-center gap-2"><History className="w-4 h-4 text-blue-500" /> Timeline</h3>
                 <span className="text-[10px] bg-gray-950 px-2 py-1 rounded-lg border border-gray-800 text-gray-500">{history.length}</span>
               </div>

               <div className="flex-grow overflow-y-auto pr-2 custom-scrollbar space-y-4">
                  {history.map((img, idx) => (
                    <button key={img.id} onClick={() => setCurrentImage(img.dataUrl)} className={`group relative w-full rounded-2xl overflow-hidden border-2 transition-all text-left ${currentImage === img.dataUrl ? 'border-blue-500 ring-4 ring-blue-500/10 shadow-2xl' : 'border-gray-800 hover:border-gray-700'}`}>
                       <div className="aspect-[4/3] w-full bg-black">
                         <img src={img.dataUrl} className="w-full h-full object-cover" alt={`Version ${history.length - idx}`} />
                       </div>
                       <div className="p-3 bg-gray-950/80 backdrop-blur-sm border-t border-gray-800">
                          <p className="text-[10px] text-gray-500 font-medium mb-1 truncate">#{history.length - idx}</p>
                          <p className="text-xs font-bold text-gray-300 truncate">{img.prompt}</p>
                       </div>
                    </button>
                  ))}
               </div>

               <div className="mt-6 pt-6 border-t border-gray-800">
                  <button onClick={() => { if(confirm("Discard project?")) window.location.reload(); }} className="w-full flex items-center justify-center gap-2 text-xs font-bold text-gray-600 hover:text-red-400 py-3 rounded-xl hover:bg-red-400/5 transition-all">
                    <RotateCcw className="w-3 h-3" /> Reset
                  </button>
               </div>
            </div>
          </div>
        )}
      </main>

      {error && (
        <div className="fixed bottom-8 left-1/2 -translate-x-1/2 bg-red-900/95 text-red-100 px-8 py-4 rounded-2xl border border-red-700 backdrop-blur-xl flex items-center gap-4 animate-in slide-in-from-bottom-4 shadow-2xl z-[100]">
          <AlertCircle className="w-5 h-5 text-red-300" />
          <p className="text-sm font-bold tracking-tight">{error}</p>
          <button onClick={() => setError(null)} className="ml-4 text-white hover:bg-white/10 p-1 rounded-full transition-colors">✕</button>
        </div>
      )}
    </div>
  );
}
